/// <summary>
/// PaffH 19.11.21
/// get Display image, if Address-Record is blocked
/// </summary>
/// <param name = "isBlocked">CustVendorBlocked</param>
/// <returns>container (ImageReference)</returns>
public static container NDXGetBlockedSymbol(CustVendorBlocked isBlocked)
{
    ImageReference imgRef;
    if (isBlocked)
    {
        imgRef = ImageReference::constructForSymbol(ImageReferenceSymbol::RedX, "@NDX:NDXBlocked");
    }
    else
    {
        imgRef = ImageReference::constructForSymbol('', "@NDX:NDXBlockedNot");
    }
    return imgRef.pack();
}
